/**
 * [2026-10-07 android-native] Android "native-ness" / Play-readiness polish.
 *
 * `/android` is gitignored and regenerated by `expo prebuild --clean`, so all
 * of this must live in a config plugin:
 *
 *  1. Predictive back (Android 14+): MainActivity opts in with
 *     android:enableOnBackInvokedCallback="true" at ACTIVITY level.
 *     The <application> flag stays "false" (Expo default) ON PURPOSE: the
 *     native call/live screens (expo-callkit CallActivity, GroupCallActivity,
 *     IncomingCallActivity, Live*Activity; expo-live-native Live*Activity)
 *     override the legacy onBackPressed() to IGNORE back ("hangup must be
 *     intentional"). With an app-wide opt-in — or targetSdk 36 on Android 16
 *     without the app-level opt-out — that override is never called and a
 *     back swipe would finish the call screen. Activity-level attributes are
 *     honored from API 34; on API 33 MainActivity simply keeps legacy back
 *     (RN 0.83 ReactActivity routes both paths through
 *     OnBackPressedDispatcher → JS BackHandler, so behavior is identical).
 *
 *  2. Per-app language (Android 13+ Settings → App languages):
 *     android:localeConfig="@xml/locales_config", generated from
 *     i18n/manifest.json (core + every remote locale) so it never drifts from
 *     what LanguageContext can actually render.
 *
 *  4. [2026-10-14 piscada-android] windowBackground do AppTheme = cor do tema
 *     do app (claro #ffffff / escuro #000000 via values-night). Antes ficava o
 *     default do Theme.AppCompat.DayNight (#fafafa / #303030 cinza): aparecia
 *     entre o splash e o 1º frame do RN, ao abrir activities nativas e atrás
 *     das telas durante as transições do native-stack → "piscada" cinza no escuro.
 *
 *  3. Legacy storage permissions stay capped at maxSdkVersion=32 with
 *     tools:replace (libraries such as expo-file-system / expo-image /
 *     expo-image-picker declare them UNCAPPED; without the replace the merged
 *     manifest would request READ_EXTERNAL_STORAGE on every API level).
 */
const fs = require('fs');
const path = require('path');
const {
  withAndroidManifest,
  withDangerousMod,
  withAndroidStyles,
  withAndroidColors,
  withAndroidColorsNight,
  AndroidConfig,
} = require('@expo/config-plugins');

const WINDOW_BG = 'chatyy_window_background';
const WINDOW_BG_LIGHT = '#ffffff'; // = Colors.background (constants/theme.js)
const WINDOW_BG_DARK = '#000000';  // = DarkColors.background ([2026-10-08 dark-black])

function withWindowBackground(config) {
  config = withAndroidColors(config, (cfg) => {
    cfg.modResults = AndroidConfig.Colors.assignColorValue(cfg.modResults, { name: WINDOW_BG, value: WINDOW_BG_LIGHT });
    return cfg;
  });
  config = withAndroidColorsNight(config, (cfg) => {
    cfg.modResults = AndroidConfig.Colors.assignColorValue(cfg.modResults, { name: WINDOW_BG, value: WINDOW_BG_DARK });
    return cfg;
  });
  config = withAndroidStyles(config, (cfg) => {
    cfg.modResults = AndroidConfig.Styles.assignStylesValue(cfg.modResults, {
      add: true,
      parent: AndroidConfig.Styles.getAppThemeGroup(),
      name: 'android:windowBackground',
      value: `@color/${WINDOW_BG}`,
    });
    return cfg;
  });
  return config;
}

const LOCALES_XML = 'locales_config';

function readLocales(projectRoot) {
  const out = [];
  try {
    const m = JSON.parse(
      fs.readFileSync(path.join(projectRoot, 'i18n', 'manifest.json'), 'utf8')
    );
    for (const l of m.core || []) out.push(l);
    for (const l of Object.keys(m.locales || {})) out.push(l);
  } catch (e) {
    // Fall back to the bundled core languages — never emit an empty config
    // (an empty <locale-config> hides the app from the Settings picker).
    out.push('pt-BR', 'en', 'es', 'pt-PT');
  }
  // Dedupe, keep pt-BR first (default language) for readability.
  return [...new Set(out)].filter((x) => /^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$/.test(x));
}

function buildLocalesXml(locales) {
  const lines = locales.map((l) => `    <locale android:name="${l}"/>`);
  return [
    '<?xml version="1.0" encoding="utf-8"?>',
    '<!-- Generated by plugins/with-android-native-polish.js from i18n/manifest.json -->',
    '<locale-config xmlns:android="http://schemas.android.com/apk/res/android">',
    ...lines,
    '</locale-config>',
    '',
  ].join('\n');
}

const STORAGE_CAPS = {
  'android.permission.READ_EXTERNAL_STORAGE': '32',
  'android.permission.WRITE_EXTERNAL_STORAGE': '32',
};

function withManifestTweaks(config) {
  return withAndroidManifest(config, (cfg) => {
    const manifest = cfg.modResults;
    manifest.manifest.$ = manifest.manifest.$ || {};
    manifest.manifest.$['xmlns:tools'] =
      manifest.manifest.$['xmlns:tools'] || 'http://schemas.android.com/tools';

    // (3) storage caps
    const perms = manifest.manifest['uses-permission'] || [];
    for (const p of perms) {
      const name = p.$?.['android:name'];
      if (name && STORAGE_CAPS[name] && p.$['tools:node'] !== 'remove') {
        p.$['android:maxSdkVersion'] = STORAGE_CAPS[name];
        p.$['tools:replace'] = 'android:maxSdkVersion';
      }
    }

    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(manifest);
    // (2) per-app language
    app.$['android:localeConfig'] = `@xml/${LOCALES_XML}`;

    // (1) predictive back — MainActivity only (see header).
    const main = (app.activity || []).find(
      (a) => a.$?.['android:name'] === '.MainActivity'
    );
    if (main) main.$['android:enableOnBackInvokedCallback'] = 'true';
    return cfg;
  });
}

function withLocalesXml(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const dir = path.join(
        cfg.modRequest.platformProjectRoot,
        'app', 'src', 'main', 'res', 'xml'
      );
      fs.mkdirSync(dir, { recursive: true });
      const locales = readLocales(cfg.modRequest.projectRoot);
      fs.writeFileSync(path.join(dir, `${LOCALES_XML}.xml`), buildLocalesXml(locales));
      return cfg;
    },
  ]);
}

module.exports = function withAndroidNativePolish(config) {
  config = withManifestTweaks(config);
  config = withLocalesXml(config);
  config = withWindowBackground(config);
  return config;
};
